// n8n Code Node - runs once for all items
const items = $input.all();

// Manila is UTC+8, no DST
const MANILA_OFFSET_MS = 8 * 60 * 60 * 1000;

function toManilaDateOnly(dateTimeObj) {
  if (!dateTimeObj || !dateTimeObj.dateTime) return null;

  // Source dateTime is UTC (per timeZone field), parse it as UTC
  const utcDate = new Date(dateTimeObj.dateTime + 'Z');
  const manilaDate = new Date(utcDate.getTime() + MANILA_OFFSET_MS);

  const pad = (n) => String(n).padStart(2, '0');
  return `${manilaDate.getUTCFullYear()}-${pad(manilaDate.getUTCMonth() + 1)}-${pad(manilaDate.getUTCDate())}`;
}

function getTodayManilaDateOnly() {
  const nowUTC = new Date();
  const nowManila = new Date(nowUTC.getTime() + MANILA_OFFSET_MS);
  const pad = (n) => String(n).padStart(2, '0');
  return `${nowManila.getUTCFullYear()}-${pad(nowManila.getUTCMonth() + 1)}-${pad(nowManila.getUTCDate())}`;
}

function categorizeDueDate(dueDateOnly) {
  if (!dueDateOnly) return 'No Due Date';

  const todayDateOnly = getTodayManilaDateOnly();

  if (dueDateOnly === todayDateOnly) {
    return 'Due Today';
  } else if (dueDateOnly < todayDateOnly) {
    return 'Overdue';
  } else {
    return 'Upcoming';
  }
}

const results = items.map((item) => {
  const json = item.json;

  const dueDateTimeManila = toManilaDateOnly(json.dueDateTime);
  const completedDateTimeManila = toManilaDateOnly(json.completedDateTime);
  const dueDateCategory = categorizeDueDate(dueDateTimeManila);

  return {
    json: {
      ...json,
      dueDateTimeManila,
      completedDateTimeManila,
      dueDateCategory
    }
  };
});

return results;

// Fields to remove from each task object
const excludeFields = [
  '@odata.etag',
  'hasAttachments',
  'categories',
  'id',
  'checklistItems@odata.context',
  'has_task_in_list',
  'has_task_in_list_verification',
  'dueDateTime',        // note: dueDateTimeManila is kept
  'completedDateTime',  // note: completedDateTimeManila is kept
];

// Helper: return a shallow copy of obj without the excluded keys
function omitFields(obj, fields) {
  const cleaned = { ...obj };
  for (const field of fields) {
    delete cleaned[field];
  }
  return cleaned;
}

// Group tasks by username + list_name
const groups = {};

for (const item of $input.all()) {
  const task = item.json;
  const username = task.metadata?.username || 'Unknown User';
  const listName = task.metadata?.list_name || 'Unknown List';
  const groupKey = `${username}::${listName}`;

  const cleanedTask = omitFields(task, excludeFields);

  if (!groups[groupKey]) {
    groups[groupKey] = {
      username: username,
      list_name: listName,
      tasks: [],
    };
  }

  groups[groupKey].tasks.push(cleanedTask);
}

// Return one item per username + list combo
return Object.values(groups).map((group) => ({ json: group }));
